// End-to-end encryption of the remote-appointment chat (WebCrypto only).
//
// Protocol "sante-saude chat v1" — the API's test double (api/tests/chat_client.py)
// implements the very same steps, and the two are cross-checked by a fixture:
//
// * identity: an ECDH P-256 key pair per user, generated here; the private key
//   is non-extractable and kept in the browser (IndexedDB, per user id); the
//   public key (JWK) is published to the server with its fingerprint
//   (SHA-256 of the uncompressed point 04||x||y);
// * conversation key: AES-256-GCM, generated by whoever opens the chat first
//   and wrapped for each participant — ephemeral ECDH with the recipient's
//   public key, HKDF-SHA256 (empty salt, info "sante-saude chat v1 kek"),
//   AES-256-GCM over the raw key with the recipient's fingerprint as
//   associated data;
// * messages: AES-256-GCM over the JSON payload {text, attachments[]} with
//   "sante-saude chat v1 message <conversation id>" as associated data;
// * attachments: AES-256-GCM over the file bytes with
//   "sante-saude chat v1 attachment <conversation id>" as associated data;
//   the IV travels inside the message payload with the name, type and size.
//
// The server relays ciphertext and sizes; it never holds a key.

const subtle = globalThis.crypto.subtle
const encoder = new TextEncoder()
const decoder = new TextDecoder()

export const PROTOCOL = 'sante-saude chat v1'
const KEK_INFO = encoder.encode(`${PROTOCOL} kek`)
const CURVE = 'P-256'

// --- encoding helpers ------------------------------------------------------------

export function toBase64(bytes) {
  let text = ''
  const view = new Uint8Array(bytes)
  for (let index = 0; index < view.length; index += 1) text += String.fromCharCode(view[index])
  return btoa(text)
}

export function fromBase64(text) {
  const binary = atob(text)
  const bytes = new Uint8Array(binary.length)
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index)
  return bytes
}

function fromBase64Url(text) {
  return fromBase64(text.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (text.length % 4)) % 4))
}

function hex(bytes) {
  return [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

function randomIv() {
  return globalThis.crypto.getRandomValues(new Uint8Array(12))
}

function publicJwkOf(jwk) {
  return { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y }
}

// --- identity -------------------------------------------------------------------------

/** SHA-256 (hex) of the uncompressed EC point: how both sides name a public key. */
export async function fingerprintOf(jwk) {
  const x = fromBase64Url(jwk.x)
  const y = fromBase64Url(jwk.y)
  const point = new Uint8Array(1 + x.length + y.length)
  point[0] = 4
  point.set(x, 1)
  point.set(y, 1 + x.length)
  return hex(await subtle.digest('SHA-256', point))
}

export async function generateIdentity() {
  const pair = await subtle.generateKey({ name: 'ECDH', namedCurve: CURVE }, false, ['deriveBits'])
  const publicJwk = publicJwkOf(await subtle.exportKey('jwk', pair.publicKey))
  return { privateKey: pair.privateKey, publicJwk, fingerprint: await fingerprintOf(publicJwk) }
}

/** An identity from a JWK that carries the private part (tests, imports). */
export async function importIdentity(privateJwk) {
  const privateKey = await subtle.importKey('jwk', { ...privateJwk, key_ops: ['deriveBits'] }, { name: 'ECDH', namedCurve: CURVE }, false, ['deriveBits'])
  const publicJwk = publicJwkOf(privateJwk)
  return { privateKey, publicJwk, fingerprint: await fingerprintOf(publicJwk) }
}

/**
 * The identity of `userId` from the store, created on first use. `store`
 * has `get(key)` / `set(key, value)` returning promises: IndexedDB in the
 * browser (CryptoKey objects are stored as such, never as bytes), a Map in
 * tests.
 */
export async function loadOrCreateIdentity(store, userId) {
  const key = `identity:${userId}`
  const saved = await store.get(key)
  if (saved && saved.privateKey && saved.publicJwk) {
    return { privateKey: saved.privateKey, publicJwk: saved.publicJwk, fingerprint: await fingerprintOf(saved.publicJwk) }
  }
  const identity = await generateIdentity()
  await store.set(key, { privateKey: identity.privateKey, publicJwk: identity.publicJwk })
  return identity
}

export function memoryStore() {
  const map = new Map()
  return { get: async (key) => map.get(key), set: async (key, value) => void map.set(key, value), delete: async (key) => void map.delete(key) }
}

/** IndexedDB-backed store (one object store, keyed by string). */
export function indexedDbStore(name = 'sante-chat') {
  function open() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(name, 1)
      request.onupgradeneeded = () => request.result.createObjectStore('items')
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error)
    })
  }
  function run(mode, action) {
    return open().then(
      (db) =>
        new Promise((resolve, reject) => {
          const transaction = db.transaction('items', mode)
          const request = action(transaction.objectStore('items'))
          request.onsuccess = () => resolve(request.result)
          request.onerror = () => reject(request.error)
          transaction.oncomplete = () => db.close()
        }),
    )
  }
  return {
    get: (key) => run('readonly', (items) => items.get(key)),
    set: (key, value) => run('readwrite', (items) => items.put(value, key)),
    delete: (key) => run('readwrite', (items) => items.delete(key)),
  }
}

// --- conversation key and envelopes ---------------------------------------------------------

export function generateConversationKey() {
  return subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt'])
}

async function importPublic(jwk) {
  return subtle.importKey('jwk', publicJwkOf(jwk), { name: 'ECDH', namedCurve: CURVE }, false, [])
}

/** KEK = HKDF-SHA256(ECDH(private, peer public)), as an AES-GCM key. */
async function keyEncryptionKey(privateKey, peerJwk) {
  const shared = await subtle.deriveBits({ name: 'ECDH', public: await importPublic(peerJwk) }, privateKey, 256)
  const base = await subtle.importKey('raw', shared, 'HKDF', false, ['deriveKey'])
  return subtle.deriveKey({ name: 'HKDF', hash: 'SHA-256', salt: new Uint8Array(0), info: KEK_INFO }, base, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt'])
}

/** Wrap the conversation key for a participant's identity key. */
export async function wrapKeyFor(conversationKey, recipientJwk) {
  const ephemeral = await subtle.generateKey({ name: 'ECDH', namedCurve: CURVE }, false, ['deriveBits'])
  const recipientFingerprint = await fingerprintOf(recipientJwk)
  const kek = await keyEncryptionKey(ephemeral.privateKey, recipientJwk)
  const iv = randomIv()
  const raw = await subtle.exportKey('raw', conversationKey)
  const wrapped = await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: encoder.encode(recipientFingerprint) }, kek, raw)
  return {
    recipient_fingerprint: recipientFingerprint,
    ephemeral_public_key: publicJwkOf(await subtle.exportKey('jwk', ephemeral.publicKey)),
    iv: toBase64(iv),
    wrapped_key: toBase64(wrapped),
  }
}

/** Open an envelope with my identity key; extractable so I can wrap it for others. */
export async function unwrapKey(envelope, privateKey) {
  const kek = await keyEncryptionKey(privateKey, envelope.ephemeral_public_key)
  const raw = await subtle.decrypt(
    { name: 'AES-GCM', iv: fromBase64(envelope.iv), additionalData: encoder.encode(envelope.recipient_fingerprint) },
    kek,
    fromBase64(envelope.wrapped_key),
  )
  return subtle.importKey('raw', raw, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt'])
}

// --- messages and attachments ------------------------------------------------------------------

function messageAad(conversationId) {
  return encoder.encode(`${PROTOCOL} message ${conversationId}`)
}

function attachmentAad(conversationId) {
  return encoder.encode(`${PROTOCOL} attachment ${conversationId}`)
}

export async function encryptMessage(conversationKey, conversationId, payload) {
  const iv = randomIv()
  const ciphertext = await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: messageAad(conversationId) }, conversationKey, encoder.encode(JSON.stringify(payload)))
  return { ciphertext: toBase64(ciphertext), iv: toBase64(iv) }
}

export async function decryptMessage(conversationKey, conversationId, message) {
  const plain = await subtle.decrypt({ name: 'AES-GCM', iv: fromBase64(message.iv), additionalData: messageAad(conversationId) }, conversationKey, fromBase64(message.ciphertext))
  return JSON.parse(decoder.decode(plain))
}

export async function encryptBlob(conversationKey, conversationId, bytes) {
  const iv = randomIv()
  const blob = await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: attachmentAad(conversationId) }, conversationKey, bytes)
  return { blob: new Uint8Array(blob), iv: toBase64(iv) }
}

export async function decryptBlob(conversationKey, conversationId, bytes, iv) {
  return subtle.decrypt({ name: 'AES-GCM', iv: fromBase64(iv), additionalData: attachmentAad(conversationId) }, conversationKey, bytes)
}

// --- safety code --------------------------------------------------------------------------------

/** 60 digits in groups of 5 from the sorted fingerprints — the same on both sides. */
export async function safetyCode(fingerprints) {
  const digest = await subtle.digest('SHA-256', encoder.encode([...fingerprints].sort().join('|')))
  const digits = BigInt(`0x${hex(digest)}`).toString().padStart(60, '0').slice(0, 60)
  return digits.match(/.{1,5}/g).join(' ')
}

/** "a1b2 c3d4 …": a fingerprint in readable groups. */
export function shortFingerprint(fingerprint) {
  return fingerprint ? fingerprint.slice(0, 32).match(/.{1,4}/g).join(' ') : ''
}
